<?php
declare(strict_types=1);
namespace App\Controllers;use App\Core\{Csrf,Request,Response,View};use App\Repositories\EpgRepository;use App\Security\Auth;use App\Services\EpgService;use Throwable;
final readonly class EpgController{public function __construct(private View $view,private EpgRepository $repo,private EpgService $service,private Csrf $csrf){}public function index(Request $r):void{$this->allow();$this->view->render('epg/index',['title'=>'EPG','sources'=>$this->repo->sources(),'csrf'=>$this->csrf]);}public function save(Request $r):void{$this->allow();$this->attempt(fn()=>$this->service->save($r->input));}public function run(Request $r):void{$this->allow();$this->attempt(fn()=>$this->service->queue($r->int('id')));}private function attempt(callable $f):never{try{$f();Response::redirect('/epg');}catch(Throwable $e){http_response_code(422);exit(htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8'));}}private function allow():void{if(!Auth::can('epg.manage')){http_response_code(403);exit('Sin permiso');}}}
